def compare(a, b):
    def parse(v):
        if not isinstance(v, str) or v == "":
            raise ValueError("invalid version: empty")
        # Strip build metadata (ignored in precedence)
        plus = v.find("+")
        if plus != -1:
            build = v[plus + 1:]
            v = v[:plus]
            if build == "" or any(
                seg == "" or any(c not in _ALNUM_HY for c in seg)
                for seg in build.split(".")
            ):
                raise ValueError("invalid build metadata")
        # Split off prerelease
        dash = v.find("-")
        if dash != -1:
            core = v[:dash]
            pre = v[dash + 1:]
        else:
            core = v
            pre = None
        # Parse core: exactly major.minor.patch
        parts = core.split(".")
        if len(parts) != 3:
            raise ValueError("invalid core version: need major.minor.patch")
        nums = []
        for p in parts:
            if p == "" or not p.isdigit() or not all(c in _DIGITS for c in p):
                raise ValueError("invalid core component")
            if len(p) > 1 and p[0] == "0":
                raise ValueError("leading zero in core component")
            nums.append(int(p))
        # Parse prerelease identifiers
        pre_ids = None
        if pre is not None:
            if pre == "":
                raise ValueError("empty prerelease")
            pre_ids = []
            for ident in pre.split("."):
                if ident == "":
                    raise ValueError("empty prerelease identifier")
                if all(c in _DIGITS for c in ident):
                    if len(ident) > 1 and ident[0] == "0":
                        raise ValueError("leading zero in numeric prerelease identifier")
                    pre_ids.append((0, int(ident), ""))  # numeric: type 0
                else:
                    if any(c not in _ALNUM_HY for c in ident):
                        raise ValueError("invalid character in prerelease identifier")
                    pre_ids.append((1, 0, ident))  # alphanumeric: type 1
        return nums, pre_ids

    def cmp(x, y):
        return (x > y) - (x < y)

    _DIGITS = "0123456789"
    _ALNUM_HY = set("0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ-")

    na, pa = parse(a)
    nb, pb = parse(b)

    # Compare core numerically
    for ca, cb in zip(na, nb):
        c = cmp(ca, cb)
        if c != 0:
            return c

    # Prerelease precedence: a version WITH prerelease < without
    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1

    # Compare prerelease identifiers left-to-right
    for ia, ib in zip(pa, pb):
        # numeric (type 0) < alphanumeric (type 1)
        c = cmp(ia[0], ib[0])
        if c != 0:
            return c
        if ia[0] == 0:
            c = cmp(ia[1], ib[1])  # both numeric
        else:
            c = cmp(ia[2], ib[2])  # both alphanumeric, ASCII lexical
        if c != 0:
            return c

    # All preceding equal: larger set wins
    return cmp(len(pa), len(pb))
